css:
.phero .sub a,.paper p a:not(.btn),.paper li a,.paper dd a{color:var(--green)}.phero .sub a{color:#7FD1A8}
.sh-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:8px}
.sh-two>div{background:#fff;border:1px solid var(--border);border-radius:16px;padding:22px 24px}
.sh-two>div.on{background:#07140F;color:#E8F0EC;border-color:#07140F}.sh-two>div.on p{color:rgba(232,240,236,.8)}
.sh-two h3,.sh-steps h3{margin:0 0 8px;font-size:20px}.sh-two p,.sh-two li{font-size:15px;line-height:1.6;color:var(--muted)}
.sh-two ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:6px}
.sh-two>div.ok{background:#EBF5F0;border-color:#CFE6DA}.sh-two>div.no{background:#F7F2E9;border-color:#E9DFCB}
.sh-note{margin-top:18px;font-size:14.5px;line-height:1.65;color:var(--muted);max-width:52em}
.sh-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:0;list-style:none;margin:8px 0 0}
.sh-three li{background:#fff;border:1px solid var(--border);border-radius:14px;padding:18px 20px;font-size:15px;line-height:1.55;color:var(--muted)}
.sh-three b{display:block;color:var(--text);margin-bottom:4px;font-size:16px}
.sh-diag{margin-top:20px;background:#FBFCFB;border:1px solid var(--border);border-radius:18px;padding:18px}.sh-diag svg{width:100%;height:auto;display:block}
.sh-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-top:8px}
.sh-steps>div{background:#fff;border:1px solid var(--border);border-radius:16px;padding:20px}
.sh-steps>div.on{background:#07140F;border-color:#07140F;color:#E8F0EC}.sh-steps>div.on p{color:rgba(232,240,236,.8)}.sh-steps>div.on a{color:#7FD1A8}
.sh-steps span{font:600 11px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--green)}.sh-steps>div.on span{color:#4BE3A2}
.sh-steps h3{margin-top:10px}.sh-steps p{font-size:14.5px;line-height:1.6;color:var(--muted)}
.sh-qa{margin:8px 0 0;display:grid;grid-template-columns:minmax(0,260px) minmax(0,1fr);gap:14px 28px}
.sh-qa dt{font-weight:700;font-size:16px;color:var(--text)}.sh-qa dd{margin:0;font-size:15px;line-height:1.6;color:var(--muted)}
.sh-read{padding-left:18px;font-size:15.5px;line-height:1.9}
code{font-family:var(--mono);font-size:.92em;background:rgba(13,13,12,.06);padding:1px 5px;border-radius:5px}.sh-two>div.on code,.sh-steps>div.on code{background:rgba(232,240,236,.1)}
@media (max-width:900px){.sh-two,.sh-three,.sh-steps,.sh-qa{grid-template-columns:minmax(0,1fr)}}
